; check.asm -- chapter 4: what runs this cartridge
; generated by gen04.py
        INCLUDE "msx.inc"
        OUTPUT "check.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
turns   EQU VARS + 16           ; the turns of the loop in one frame
sum     EQU VARS + 18           ; the sum of page 0
BOTTOM  EQU $FC48               ; BIOS work area: the lowest address of RAM
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 1, $C0          ; display on, no interrupts: the program polls
        in a, (VDP_CTRL)        ; clear a flag left from before
.sync:  in a, (VDP_CTRL)        ; wait for the frame flag ...
        rlca
        jr nc, .sync
        ld hl, 0
turn:   inc hl                  ; ... then count until it comes up again
        in a, (VDP_CTRL)
        rlca
        jr nc, turn
        ld (turns), hl
        ld hl, 0                ; the sum of $0000-$3FFF, the BIOS's page
        ld ix, 0
        ld b, 0
.add:   ld c, (hl)
        add ix, bc
        inc hl
        ld a, h
        cp $40
        jr nz, .add
        ld (sum), ix
        ld b, 1
        ld c, 0
        ld hl, t_title
        call puts
        ld b, 3
        ld c, 0
        ld hl, t_asm
        call puts
        ld c, 11
        ld hl, t_ver            ; written by the assembler, not by the program
        call puts
        ld b, 5
        ld c, 0
        ld hl, t_sum
        call puts
        ld c, 11
        ld a, (sum + 1)
        call puthex
        ld a, (sum)
        call puthex
        ld b, 7      ; $002B, bit 7: 1 for 50 Hz, 0 for 60
        ld c, 0
        ld hl, t_2b
        call puts
        ld c, 11
        ld a, ($002B)
        call puthex
        inc c
        inc c
        ld hl, t_60
        ld a, ($002B)
        rlca
        jr nc, .hz
        ld hl, t_50
.hz:    call puts
        ld b, 8     ; $002D: 0 MSX1, 1 MSX2, 2 MSX2+, 3 turbo R
        ld c, 0
        ld hl, t_2d
        call puts
        ld c, 11
        ld a, ($002D)
        call puthex
        inc c
        inc c
        ld a, ($002D)
        cp 4
        jr c, .known
        ld a, 4
.known: add a, a
        ld e, a
        ld d, 0
        ld hl, names
        add hl, de
        ld a, (hl)
        inc hl
        ld h, (hl)
        ld l, a
        call puts
        ld b, 10
        ld c, 0
        ld hl, t_ram
        call puts
        ld c, 11
        ld a, (BOTTOM + 1)
        call puthex
        ld a, (BOTTOM)
        call puthex
        ld b, 12
        ld c, 0
        ld hl, t_turns
        call puts
        ld c, 11
        ld hl, (turns)
        call putd16
        ld hl, t_of
        call puts
done:   jr done

t_title: db "check: what runs this cartridge", 0
t_asm:  db "assembler", 0
t_ver:  db "sjasmplus ", __VERSION__, 0
t_sum:  db "BIOS sum", 0
t_2b:   db "$002B", 0
t_50:   db "50 Hz", 0
t_60:   db "60 Hz", 0
t_2d:   db "$002D", 0
t_ram:  db "RAM from", 0
t_turns: db "turns", 0
t_of:   db " of 37 T", 0
names:  dw n0, n1, n2, n3, n4
n0:     db "MSX1", 0
n1:     db "MSX2", 0
n2:     db "MSX2+", 0
n3:     db "turbo R", 0
n4:     db "?", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; putd16: HL = a number (0-65535) as five characters, right-aligned.
;         B = row, C = column; C moves on by 5. Uses A, DE, HL.
putd16: push bc
        ld de, d16buf
        ld bc, -10000
        call .digit
        ld bc, -1000
        call .digit
        ld bc, -100
        call .digit
        ld bc, -10
        call .digit
        ld a, l
        add a, '0'
        ld (de), a              ; the units, always printed
        ld hl, d16buf
        ld b, 4
.blank: ld a, (hl)              ; leading zeros become spaces
        cp '0'
        jr nz, .print
        ld (hl), ' '
        inc hl
        djnz .blank
.print: pop bc
        ld hl, d16buf
        ld e, 5
.out:   ld a, (hl)
        call putc
        inc c
        inc hl
        dec e
        jr nz, .out
        ret
.digit: ld a, '0' - 1           ; how many times BC fits: subtract until it goes below
.sub:   inc a
        add hl, bc              ; BC is negative: the carry means it still fitted
        jr c, .sub
        sbc hl, bc              ; one too many: add it back (the carry is clear)
        ld (de), a
        inc de
        ret
d16buf  EQU VARS + 4            ; 5 bytes of RAM, after numbuf
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
